using Seamless.Management;
using Seamless.Management.Server;

namespace Management.Tests;

public sealed class ReadAuditDefaults{
    [Fact]public void ParameterlessOptionsUseOneMinuteAndFiveSeconds(){var options=new ReadAuditOptions();Assert.Equal(TimeSpan.FromMinutes(1),options.Window);Assert.Equal(TimeSpan.FromSeconds(5),options.Interval);options.Validate();}
    [Fact]public void ExistingExplicitConstructorStillUsesTheGivenWindow(){var options=new ReadAuditOptions(TimeSpan.FromMinutes(3));Assert.Equal(TimeSpan.FromMinutes(3),options.Window);Assert.Equal(TimeSpan.FromSeconds(5),options.Interval);}
    [Fact]public void NormalServerUsesDefaultsAndExplicitValuesTakePrecedence(){var defaults=ReadAuditOptions.ForServer(5,null,null)!;Assert.Equal(TimeSpan.FromMinutes(1),defaults.Window);Assert.Equal(TimeSpan.FromSeconds(5),defaults.Interval);var selected=ReadAuditOptions.ForServer(5,"120","2.5")!;Assert.Equal(TimeSpan.FromMinutes(2),selected.Window);Assert.Equal(TimeSpan.FromMilliseconds(2500),selected.Interval);var intervalOnly=ReadAuditOptions.ForServer(5,null,"3")!;Assert.Equal(TimeSpan.FromMinutes(1),intervalOnly.Window);Assert.Equal(TimeSpan.FromSeconds(3),intervalOnly.Interval);}
    [Theory][InlineData(3)][InlineData(4)]public void LegacyStorageIsNotAutomaticallyEnabledOrUpgraded(int format){Assert.Null(ReadAuditOptions.ForServer(format,null,null));Assert.Equal("MigrationRequired",Assert.Throws<ManagementException>(()=>ReadAuditOptions.ForServer(format,"60",null)).Code);Assert.Equal("MigrationRequired",Assert.Throws<ManagementException>(()=>ReadAuditOptions.ForServer(format,null,"5")).Code);}
    [Fact]public void ExplicitStopAndConflictingOptionsAreDistinguished(){Assert.Null(ReadAuditOptions.ForServer(5,null,null,true));Assert.Throws<ArgumentException>(()=>ReadAuditOptions.ForServer(5,"60",null,true));Assert.Throws<ArgumentException>(()=>ReadAuditOptions.ForServer(5,null,"5",true));}
    [Fact]public async Task AMinuteSeparatesUserQueryCodePolicyAndDatabase(){var options=new ReadAuditOptions();var at=new DateTimeOffset(2026,11,4,0,0,0,TimeSpan.Zero);var key=new AuditReadKey(at,at+options.Window,Guid.NewGuid(),"user","db","query","dll-1",1);var counts=new Dictionary<AuditReadKey,long>();await using var buffer=new Seamless.Management.Server.ReadAuditBuffer(options,(_,rows,_)=>{foreach(var row in rows){counts[row.Key]=counts.GetValueOrDefault(row.Key)+row.Count;}return ValueTask.CompletedTask;},false);Assert.True(buffer.Record(key));Assert.True(buffer.Record(key));foreach(var variant in new[]{key with{SubjectId="other"},key with{QueryId="other"},key with{CodeVersion="dll-2"},key with{PolicyVersion=2},key with{PolicyVersion=null},key with{Database="other"}}){Assert.True(buffer.Record(variant));}Assert.True(await buffer.FlushAsync());Assert.Equal(7,counts.Count);Assert.Equal(2,counts[key]);Assert.Equal(8,counts.Values.Sum());Assert.All(counts.Keys,item=>Assert.Equal(TimeSpan.FromMinutes(1),item.WindowEnd-item.WindowStart));}
    [Theory][InlineData("0",null)][InlineData("86401",null)][InlineData(null,"0")][InlineData(null,"86401")][InlineData("bad",null)][InlineData(null,"NaN")][InlineData(null,"Infinity")][InlineData(null,"1e99")][InlineData("99999999999",null)]public void InvalidValuesDoNotSilentlyUseDefaults(string? window,string? interval){Assert.Throws<ArgumentException>(()=>ReadAuditOptions.ForServer(5,window,interval));}
}
